import{_ as o,o as t,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"How OrbySystems is different","description":"","frontmatter":{"title":"How OrbySystems is different"},"headers":[],"relativePath":"docs/overview/how-orby-is-different.md","filePath":"docs/overview/how-orby-is-different.md","lastUpdated":1794290851000}'),a={name:"docs/overview/how-orby-is-different.md"};function n(i,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="how-orbysystems-is-different" tabindex="-1">How OrbySystems is different <a class="header-anchor" href="#how-orbysystems-is-different" aria-label="Permalink to &quot;How OrbySystems is different&quot;">​</a></h1><h2 id="your-computer-does-the-work" tabindex="-1">Your computer does the work <a class="header-anchor" href="#your-computer-does-the-work" aria-label="Permalink to &quot;Your computer does the work&quot;">​</a></h2><p>The built-in models run on your computer. Once setup and model downloads finish, local analysis can work with Wi-Fi off. Connecting a cloud model or an online tool is optional; <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Models and your data</a> explains what those choices send outside your computer.</p><h2 id="ai-works-through-controlled-tools" tabindex="-1">AI works through controlled tools <a class="header-anchor" href="#ai-works-through-controlled-tools" aria-label="Permalink to &quot;AI works through controlled tools&quot;">​</a></h2><p>OrbySystems gives the model specific tools for the project. Code the model generates runs in a restricted workspace, rather than with unrestricted access to your personal files. Its network access is controlled separately in <a href="/docs/settings/agent">Settings → Agent</a>.</p><p>Statement parsers run in their own sandbox with no network access. See <a href="/docs/privacy-and-security/sandboxing">Sandboxing</a> for the distinction.</p><h2 id="follow-the-evidence" tabindex="-1">Follow the evidence <a class="header-anchor" href="#follow-the-evidence" aria-label="Permalink to &quot;Follow the evidence&quot;">​</a></h2><p>Recipes calculate financial results from your records. Chat answers show evidence marks so you can distinguish traced figures from estimates or figures that need review. Follow a source or drill-down to inspect the underlying data; review assumptions before relying on a projection.</p><h2 id="bring-statements-not-bank-passwords" tabindex="-1">Bring statements, not bank passwords <a class="header-anchor" href="#bring-statements-not-bank-passwords" aria-label="Permalink to &quot;Bring statements, not bank passwords&quot;">​</a></h2><p>Add statements you already have, or use the <a href="/docs/tools/statement-agents">Statement Download Agent</a> after signing in to your bank yourself. The agent&#39;s job is collecting statements, not making financial decisions or transactions.</p><p>If a statement format is unsupported, <a href="/docs/tools/add-new-institution">Add New Institution</a> helps you prepare and review a privacy-protected sample for support. Sharing that sample is your choice.</p>',11)])])}const f=o(a,[["render",n]]);export{p as __pageData,f as default};
